describe('Search Result Highlighting', () => {
    beforeEach(() => {
        cy.visit('/search'); // Adjust the URL to your application's search page
    });

    it('should highlight search terms in the result snippets', () => {
        const searchTerm = 'Cypress';
        cy.get('input[name="search"]').type(searchTerm);
        cy.get('button[type="submit"]').click();

        cy.get('.result-snippet').each(($snippet) => {
            cy.wrap($snippet).should('contain.text', searchTerm);
            cy.wrap($snippet).find('.highlight').should('exist');
        });
    });

    it('should not highlight terms that are not in the results', () => {
        const searchTerm = 'NonExistentTerm';
        cy.get('input[name="search"]').type(searchTerm);
        cy.get('button[type="submit"]').click();

        cy.get('.result-snippet').each(($snippet) => {
            cy.wrap($snippet).should('not.contain.text', searchTerm);
            cy.wrap($snippet).find('.highlight').should('not.exist');
        });
    });
});
